@app.route("/network/diagnose", methods=["POST"])
def diagnose():
    data = request.get_json()
    if not data or "command" not in data or "target" not in data:
        return jsonify({"error": "Missing parameters"}), 400

    command = data["command"]
    target = data["target"]

    # 1. 白名单校验：命令必须存在于预定义列表中
    if command not in ALLOWED_COMMANDS:
        return jsonify({"error": "Command not allowed"}), 403

    # 2. target 格式校验：仅允许 IP 或域名（字母数字、点、连字符）
    if not target or len(target) > 255:
        return jsonify({"error": "Invalid target"}), 400
    if not all(c.isalnum() or c in ".-" for c in target):
        return jsonify({"error": "Invalid target format"}), 400

    # 3. 构造参数列表：从白名单取基础命令，加上 target 作为参数
    cmd_list = ALLOWED_COMMANDS[command] + [target]

    # 4. 使用 subprocess.run 且 shell=False（列表参数，无 shell 解释）
    try:
        result = subprocess.run(
            cmd_list,
            capture_output=True,
            text=True,
            timeout=10,
            shell=False
        )
        return jsonify({"stdout": result.stdout, "stderr": result.stderr})
    except subprocess.TimeoutExpired:
        return jsonify({"error": "Command timed out"}), 504
    except Exception as e:
        return jsonify({"error": str(e)}), 500

