    // Query user from database
    const user = await getUserByUsername(username);
    if (!user) {
      // Generic error to prevent user enumeration
      return res.status(200).json({ message: 'If account exists, reset email sent' });
    }

    // Verify email matches user record
    if (user.email !== email) {
      return res.status(200).json({ message: 'If account exists, reset email sent' });
    }

    // Generate secure token
    const token = generateResetToken();

    // Store token in database with expiry (15 minutes)
    await db.query(
      'INSERT INTO password_resets (user_id, token, expires_at) VALUES (?, ?, DATE_ADD(NOW(), INTERVAL 15 MINUTE))',
      [user.id, token]
    );

    // Send email with reset link
    await sendResetEmail(email, token);

    return res.status(200).json({ message: 'If account exists, reset email sent' });
  } catch (error) {
    console.error('Password reset error:', error);
    return res.status(500).json({ error: 'Internal server error' });
  }
});

