from flask import Flask, request, jsonify, session
from werkzeug.security import check_password_hash
import re

app = Flask(__name__)
app.secret_key = "a-very-secure-random-secret-key-2024"

# 模拟用户数据库（实际应为数据库查询）
USERS = {
    "alice": {"password_hash": "pbkdf2:sha256:260000$abc123", "role": "admin"},
    "bob": {"password_hash": "pbkdf2:sha256:260000$def456", "role": "user"}
}

@app.route("/login", methods=["POST"])
def login():
    """用户登录接口"""
    data = request.get_json()
    username = data.get("username", "")
    password = data.get("password", "")

    # 防御层1: 白名单校验用户名，仅允许字母数字和下划线
    if not re.match(r"^[a-zA-Z0-9_]+$", username):
        return jsonify({"error": "invalid_username"}), 400

    # 防御层2: 密码长度限制，防止超长输入导致哈希计算 DoS
    if len(password) > 128:
        return jsonify({"error": "password_too_long"}), 400

    # 防御层3: 从预定义字典查询，而非拼接 SQL
    user_record = USERS.get(username)
    if user_record is None:
        return jsonify({"error": "invalid_credentials"}), 401

    # 防御层4: 使用 werkzeug 的安全哈希比对，避免时序攻击
    if not check_password_hash(user_record["password_hash"], password):
        return jsonify({"error": "invalid_credentials"}), 401

    # 防御层5: 会话固定防护——登录成功后重新生成 session ID
    session.clear()
    session["username"] = username
    session["role"] = user_record["role"]

    return jsonify({"message": "login_success", "role": user_record["role"]}), 200

@app.route("/profile", methods=["GET"])
def profile():
    """获取当前用户信息"""
    # 防御层6: 会话中获取用户名，而非从请求参数读取
    username = session.get("username")
    if username is None:
        return jsonify({"error": "unauthorized"}), 401

    # 防御层7: 再次校验，防止会话被篡改后注入
    if not re.match(r"^[a-zA-Z0-9_]+$", username):
        session.clear()
        return jsonify({"error": "session_invalid"}), 403

    # 防御层8: 仅返回白名单字段，避免信息泄露
    user_record = USERS.get(username)
    if user_record is None:
        session.clear()
        return jsonify({"error": "user_not_found"}), 404

    return jsonify({"username": username, "role": user_record["role"]}), 200

if __name__ == "__main__":
    app.run(debug=False)  # 生产环境禁用 debug

// docker-entrypoint.js
const { execFile } = require('child_process');
const fs = require('fs');
const path = require('path');

const ALLOWED_COMMANDS = new Set(['build', 'test', 'deploy']);

function validateCommand(command) {
  if (!ALLOWED_COMMANDS.has(command)) {
    throw new Error(`Command '${command}' not allowed`);
  }
  return command;
}

function runContainerCommand(command, args) {
  // 第8行：使用 execFile 而非 exec，强制列表参数传递
  return new Promise((resolve, reject) => {
    execFile(command, args, { shell: false }, (error, stdout, stderr) => {
      if (error) {
        reject(error);
        return;
      }
      resolve({ stdout, stderr });
    });
  });
}

async function main() {
  const args = process.argv.slice(2);

  // 第22行：解析入口参数，格式为 "command|arg1|arg2"
  if (args.length !== 1) {
    console.error('Usage: node entrypoint.js "command|arg1|arg2"');
    process.exit(1);
  }

  const parts = args[0].split('|');
  const command = parts[0];
  const commandArgs = parts.slice(1);

  // 第31行：白名单校验命令
  const safeCommand = validateCommand(command);

  // 第34行：参数清洗 - 移除空字符串和null字节
  const sanitizedArgs = commandArgs
    .filter(arg => arg && arg.length > 0)
    .map(arg => arg.replace(/\0/g, ''));

  // 第39行：执行命令，参数以数组形式传递
  const result = await runContainerCommand(safeCommand, sanitizedArgs);
  console.log(result.stdout);
}

main().catch(err => {
  console.error(`Execution failed: ${err.message}`);
  process.exit(1);
});

